// using sdf base functions to paint simple UI elements with automatic and analytic AA (AAAA) based on the nature of SDFs

const float SceneScaleSpeed = 0.5;
const float SceneMinScale = 3.0;
const float SceneMaxScale = 0.5;



vec2 Rotate(in vec2 p, in float angle)
{
    vec2 cossin = vec2( cos(angle), -sin(angle));
    return vec2(dot(p, cossin), dot(p, vec2(-cossin.y, cossin.x)));
}

// sd functions from: https://iquilezles.org/articles/distfunctions2d/
float sdPie( in vec2 p, in vec2 o, in float a1, in float a2, in float r )
{
    p -= o;
    p = Rotate(p, -(a1+a2)*0.5);

    float angle = a2-a1;
    vec2 c = vec2(sin(angle*0.5), cos(angle*0.5));

    p.x = abs(p.x);
    float l = length(p) - r;
    float m = length(p-c*clamp(dot(p,c),0.0,r)); // c=sin/cos of aperture
    return max(l,m*sign(c.y*p.x-c.x*p.y));
}

vec4 SdfColorize(in float sd, vec3 color, in float scale)
{
    scale = clamp(scale, 0.2, 1.0);

    // transform SDF to good looking per-pixel gradient for AA
    sd = clamp(-sd*50.0/scale, 0.0, 1.0);

    //color *= min(sd*1000.0, 1.0); // smooth blend with the background
    color *= sd*sd*sd;  // black border

    return vec4(color, sd);
}

mat2 MakeRotationScaleTransform(in float angle, in float scale)
{
    float s = sin(angle);
    float c = cos(angle);

    mat2 R = mat2(+c, -s,
                  +s, +c);
    mat2 S = mat2(scale, 0.0,
                  0.0, scale);
    return R * S;
}

vec4 ComputeSceneColor(in vec2 p, in float scale)
{
    mat2 T = MakeRotationScaleTransform( iTime*0.6, scale);
    p = p*T;

    float Anim = sin(iTime)*0.5 + 0.5;

    float k1 = Anim * 6.28 * 0.25;
    float k2 = Anim * 6.28 * 0.50;
    float k3 = Anim * 6.28 * 0.75;
    float k4 = Anim * 6.28;

    vec4 col = vec4(0.0, 0.0, 0.0,0.0);
    col += SdfColorize(sdPie(p, vec2(0.0, 0.0), 0.0, k1, 0.7), vec3(0.3, 0.8, 0.3), scale);
    col += SdfColorize(sdPie(p, vec2(0.0, 0.0), k1, k2, 0.7), vec3(1.0, 0.9, 0.0), scale);
    col += SdfColorize(sdPie(p, vec2(0.0, 0.0), k2, k3, 0.7), vec3(0.8, 0.4, 0.7), scale);
    col += SdfColorize(sdPie(p, vec2(0.0, 0.0), k3, k4, 0.7), vec3(0.35, 0.5, 0.8), scale);
    col += SdfColorize(sdPie(p, vec2(0.0, 0.0), k4, 6.28, 0.7), vec3(0.75, 0.35, 0.3), scale);

    return col;
}

vec3 ComputeBackground(in vec2 p)
{
    p *= 0.5;
    p.x += iTime*0.05;

    vec2 n = vec2(cos(p.y*20.0+iTime*1.0), sin(p.x*20.0+iTime*1.0)) * 0.01;

    float tex = texture(iChannel0, p + n).r;

    tex = -tex*tex + 2.0*tex;  // "square root"

    vec3 col = mix(vec3(1.0,1.0,1.0), vec3(0.2,0.6,0.8), tex);
    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 FragCoordNorm = (fragCoord*2.0-iResolution.xy)/iResolution.y;

    float SceneScale = mix(SceneMinScale, SceneMaxScale, sin(iTime*SceneScaleSpeed)*0.5 + 0.5);

    vec4 ColorScene = ComputeSceneColor(FragCoordNorm, SceneScale);

    float Shadow = ComputeSceneColor(FragCoordNorm + vec2(-0.05,0.05)/SceneScale, SceneScale).w;

    vec3 colb = ComputeBackground(FragCoordNorm) * (1.0 - Shadow*0.5);

    vec3 col = mix(colb, ColorScene.rgb, ColorScene.a);

    fragColor = vec4(col,1.0);
}
